import datetime
import re

from moler.exceptions import ParsingDone

from ta_moler.events.emssim.genericemssim_textualevent import GenericEMSSIMTextualEvent


class FileLoadPrepare(GenericEMSSIMTextualEvent):
    """FileLoadPrepare event class."""

    def __init__(self, connection, file_type=r"\w+File", till_occurs_times=1, runner=None):
        """
        Event for 'FileLoadPrepare'.

        :param connection: moler connection to device, terminal when command is executed
        :param file_type: type of file eg: measurementFile, allConfigurationPlanFile
        :param till_occurs_times: number of event occurrence
        """
        super(FileLoadPrepare, self).__init__(connection=connection, runner=runner, till_occurs_times=till_occurs_times)

        self._mode = ""
        self._key = ""
        self._current_ret = {}

        # 09:30:26          |* NE reports measurementFile ready for upload
        self._re_file_ready_to_upload = re.compile(fr"NE reports (?P<FILE_TYPE>{file_type}) ready for upload")

    def on_new_line(self, line, is_full_line):
        """
        Parse output from EMSSIM.

        :param line: Line to parse, line is trimmed.
        :param is_full_line: True if new line character was removed from line, False otherwise.
        :return: None
        """
        if is_full_line:
            try:
                self._file_load_prepare(line)
                self._file_ready_to_upload(line)
                self._parse_key(line)
                self._parse_pair_key_value(line)
                self._parse_value(line)
                self._file_load_completed(line)
            except ParsingDone:
                pass

    # 09:30:26 BTSOM   <|FileLoadPrepare (Seq=19)
    _re_file_load_prepare = re.compile(r"BTSOM\s+<\|FileLoadPrepare")

    def _file_load_prepare(self, line):
        """
        Process if FileLoadPrepare was received.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._regex_helper.search_compiled(FileLoadPrepare._re_file_load_prepare, line):
            self._mode = "file_load_prepare"
            raise ParsingDone()

    def _file_ready_to_upload(self, line):
        """
        Process if file ready to upload was received.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._mode == "file_load_prepare" and self._regex_helper.search_compiled(self._re_file_ready_to_upload, line):
            self._current_ret["file_type"] = self._regex_helper.group("FILE_TYPE")
            self._mode = "ready_to_upload"
            raise ParsingDone()

    # * Downloading file:
    _re_key = re.compile(r"\|\*?\s+(?P<KEY>.*?):$")

    def _parse_key(self, line):
        """
        Process key.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._mode == "ready_to_upload" and self._regex_helper.search_compiled(FileLoadPrepare._re_key, line):
            self._key = self._regex_helper.group("KEY")
            raise ParsingDone()

    # |    serverAddress => 10.0.1.2
    _re_pair_key_value = re.compile(r"\|\s+(?P<KEY>.*?)\s+=>\s+(?P<VALUE>.*)")

    def _parse_pair_key_value(self, line):
        """
        Process pair key => value.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._key and self._regex_helper.search_compiled(FileLoadPrepare._re_pair_key_value, line):
            if self._key not in self._current_ret:
                self._current_ret[self._key] = {}
            self._current_ret[self._key][self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            raise ParsingDone()

    # |  /home/flexi1/UPLOADS/KEYSTATS/PM.BTS-1.20200409.073000.ANY.raw.gz
    _re_parse_value = re.compile(r"\|\s+(?P<VALUE>.*)")

    def _parse_value(self, line):
        """
        Process value.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._key and self._regex_helper.search_compiled(FileLoadPrepare._re_parse_value, line):
            self._current_ret[self._key] = self._regex_helper.group("VALUE")
            raise ParsingDone()

    # 09:30:26 BTSOM   >|FileLoadCompleted (Seq=19)
    re_file_load_completed = re.compile(r"BTSOM\s+>\|FileLoadCompleted")

    def _file_load_completed(self, line):
        """
        Process if FileLoadPrepare was received.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._key and self._regex_helper.search_compiled(FileLoadPrepare.re_file_load_completed, line):
            self._current_ret["time"] = self._last_recv_time_data_read_from_connection
            self.event_occurred(event_data=self._current_ret)
            self._current_ret = {}
            self._mode = ""
            self._key = ""
            raise ParsingDone()


